import math
import numpy as np


# MR1: Linear interpolation towards 1.0.
# Since x in [0, 1], (1 + x) / 2 >= x.
# Therefore, program(r_1(x)) >= program(x).
def r_1(x: float) -> float:
    return (1.0 + float(x)) / 2.0


def R_1(y_orig: float, y_new: float) -> bool:
    if not (math.isfinite(y_orig) and math.isfinite(y_new)):
        return False
    # Use a small negative tolerance to account for floating-point imprecision
    return y_new - y_orig >= -1e-12


# MR2: Square root transform.
# For x in [0, 1], sqrt(x) >= x.
# Therefore, program(r_2(x)) >= program(x).
def r_2(x: float) -> float:
    return math.sqrt(float(x))


def R_2(y_orig: float, y_new: float) -> bool:
    if not (math.isfinite(y_orig) and math.isfinite(y_new)):
        return False
    return y_new - y_orig >= -1e-12


# MR3: Constant upper-bound mapping.
# For x in [0, 1], 1.0 >= x.
# Therefore, program(1.0) >= program(x).
def r_3(x: float) -> float:
    return 1.0


def R_3(y_orig: float, y_new: float) -> bool:
    if not (math.isfinite(y_orig) and math.isfinite(y_new)):
        return False
    return y_new - y_orig >= -1e-12
